.btn{display:inline-flex;align-items:center;gap:8px;background:var(--ink);color:var(--paper-2);font-weight:700;font-size:13.5px;padding:11px 18px;border-radius:0;transition:.14s;font-family:var(--sans)}
.btn:hover{background:#000;box-shadow:3px 3px 0 var(--yellow)}
.btn svg{width:16px;height:16px}
.btn.y{background:var(--yellow);color:var(--on-yellow)}.btn.y:hover{background:var(--yellow-2);box-shadow:3px 3px 0 var(--ink);color:var(--on-yellow)}
.btn.ghost{background:transparent;border:1px solid var(--ink);color:var(--ink)}.btn.ghost:hover{background:var(--ink);color:var(--paper-2);box-shadow:none}
.btn.sm{padding:8px 13px;font-size:12.5px}
.btn.copied{background:var(--ok);border-color:var(--ok);color:#fff;transition:background .15s,border-color .15s}

.pill{display:inline-flex;align-items:center;gap:6px;font-size:11px;font-weight:700;padding:4px 9px;border-radius:0;text-transform:uppercase;letter-spacing:.05em}
.pill.ok{background:var(--ok-bg);color:var(--ok)}.pill.warn{background:var(--warn-bg);color:var(--warn)}
.pill.info{background:var(--info-bg);color:var(--info)}.pill.bad{background:var(--bad-bg);color:var(--bad)}.pill.mut{background:var(--paper-3);color:var(--muted)}

/* ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â HR INFORMATION FEED ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â Shared by People & Culture and the article page.
   Additive only ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â no existing component is restyled. */
.hrf{display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:14px}
.hrf-card{display:flex;flex-direction:column;background:var(--paper-2);border:1px solid var(--line);
  text-decoration:none;color:inherit;overflow:hidden;
  transition:box-shadow .18s,transform .18s,border-color .18s}
.hrf-card:hover{transform:translateY(-2px);border-color:var(--line-2);
  box-shadow:0 2px 4px rgba(18,18,16,.03),0 18px 34px -24px rgba(18,18,16,.28)}
.hrf-cover{display:block;width:100%;aspect-ratio:16/9;overflow:hidden;
  background:var(--paper-3);border-bottom:1px solid var(--line)}
.hrf-cover img{width:100%;height:100%;object-fit:cover;display:block;
  transition:transform .4s cubic-bezier(.2,.8,.3,1)}
.hrf-card:hover .hrf-cover img{transform:scale(1.05)}
.hrf-body{display:flex;flex-direction:column;flex:1;padding:16px 18px}
.hrf-top{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:9px}
.hrf-date{margin-left:auto;font-size:11.5px;color:var(--muted);font-weight:600;white-space:nowrap}
.hrf-title{font-weight:700;font-size:16px;letter-spacing:-.015em;line-height:1.3;margin-bottom:6px}
.hrf-card:hover .hrf-title{text-decoration:underline;text-underline-offset:3px;
  text-decoration-color:var(--yellow)}
.hrf-sum{font-size:13px;line-height:1.6;color:var(--muted);margin-bottom:13px;
