.hrf-foot{display:flex;align-items:center;gap:7px;margin-top:auto;padding-top:11px;
  border-top:1px solid var(--line);font-size:11.5px;color:var(--muted);flex-wrap:wrap}
.hrf-dot{opacity:.5}
.hrf-more{margin-left:auto;font-weight:800;font-size:11px;letter-spacing:.05em;
  text-transform:uppercase;color:var(--ink);white-space:nowrap}
.hrf-card:hover .hrf-more{color:var(--ink)}

/* ── NOTIFICATIONS ──
   One stack for the whole Hub, bottom-centre, three seconds each.

   What this replaced: a full-width banner at the top of <main>, borrowing .pill
   for its look, which collapsed itself by animating max-height, padding and
   margin. Those are layout properties — the browser re-flowed the page on every
   frame of the dismissal, which is what made it judder — and a notice at the
   top of the document pushed the whole page down as it arrived and pulled it
   back up as it left.

   Only opacity and transform move here, so the compositor does the work and
   nothing else on the page is touched. There is deliberately no scale() in the
   transform: scaling text resamples the glyphs mid-flight and it reads as
   blurry, which is the "pixeled" look. A translate leaves the type crisp.

   Both themes come free: the ground, the border and the type are all tokens.
   Fixed at 900 — above the page and the two floating buttons (860), below the
   confirmation dialog (2000), which must never be covered by a notice. */
.tst-wrap{position:fixed;left:50%;bottom:22px;transform:translateX(-50%);
  z-index:900;display:flex;flex-direction:column;align-items:center;
  gap:10px;width:max-content;max-width:min(92vw,560px);
  /* The stack itself must not swallow clicks in the gaps between notices. */
  pointer-events:none}
.tst{pointer-events:auto;display:flex;align-items:center;gap:11px;
  padding:12px 13px 12px 15px;border-radius:14px;max-width:100%;
  background:var(--paper-2);color:var(--ink);border:1px solid var(--line-2);
  box-shadow:0 18px 44px -22px rgba(18,18,16,.5),
             0 2px 6px rgba(18,18,16,.06);
  font-size:13.5px;font-weight:600;line-height:1.4;text-align:left;
  opacity:0;transform:translate3d(0,14px,0);
  transition:opacity .24s cubic-bezier(.32,.72,0,1),
             transform .32s cubic-bezier(.32,.72,0,1)}
.tst.in{opacity:1;transform:translate3d(0,0,0)}
.tst.out{opacity:0;transform:translate3d(0,10px,0)}
.tst-ic{flex:none;display:flex;align-items:center;color:var(--ok)}
.tst.warn .tst-ic{color:var(--warn)}
.tst.bad .tst-ic{color:var(--bad)}
.tst-t{flex:1;min-width:0}
.tst-x{flex:none;background:none;border:0;padding:3px;margin:-3px -2px -3px 0;
  color:var(--muted);cursor:pointer;font-size:16px;line-height:1;
  font-family:inherit;border-radius:8px;
  transition:color .14s,background .14s}
.tst-x:hover{color:var(--ink);background:var(--paper-3)}
.tst-x:focus-visible{outline:2px solid var(--ink);outline-offset:1px}
@media(max-width:560px){
  .tst-wrap{left:12px;right:12px;bottom:14px;transform:none;
    width:auto;max-width:none;align-items:stretch}
}
@media(prefers-reduced-motion:reduce){
  .tst{transition:opacity .12s linear}
  .tst,.tst.in,.tst.out{transform:none}
}

input,select,textarea{font-family:inherit;font-size:14px}
.field{margin-bottom:14px}
.field label{display:block;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);margin-bottom:7px}
.field input,.field select,.field textarea{width:100%;border:1px solid var(--line-2);background:var(--paper-2);border-radius:0;padding:10px 12px;outline:none;transition:.15s;color:var(--ink)}
.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--ink);box-shadow:inset 0 -2px 0 var(--yellow)}
.row{display:grid;gap:14px}.row.c2{grid-template-columns:1fr 1fr}.row.c3{grid-template-columns:1fr 1fr 1fr}

@keyframes rise{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
.rise{animation:rise .5s cubic-bezier(.2,.7,.2,1) both}
table{width:100%;border-collapse:collapse}
th{text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);font-weight:700;padding:10px 12px;border-bottom:1px solid var(--ink)}
td{padding:13px 12px;border-bottom:1px solid var(--line);font-size:14px}
tr:last-child td{border-bottom:none}tbody tr:hover{background:var(--paper)}

.stepper{display:flex;align-items:flex-start;margin:6px 0}
.step{flex:1;text-align:center;position:relative}
.step .ball{width:30px;height:30px;background:var(--paper-3);color:var(--muted);margin:0 auto 8px;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:13px;border:1px solid var(--line-2);position:relative;z-index:2;font-family:var(--mono)}
.step.done .ball{background:var(--ok);color:#fff;border-color:var(--ok)}
.step.active .ball{background:var(--yellow);color:var(--on-yellow);border-color:var(--yellow)}
.step .lbl{font-size:11.5px;font-weight:700}.step .sub{font-size:10.5px;color:var(--muted)}
.step::before{content:"";position:absolute;top:15px;left:-50%;width:100%;height:1px;background:var(--line-2);z-index:1}
.step:first-child::before{display:none}.step.done::before,.step.active::before{background:var(--ok)}

/* max-height is the collapse target for .fade-out; keep it roomy enough that a
   two-line notice is not clipped while it is still on screen. */
.modal-bg{position:fixed;inset:0;background:rgba(18,18,16,.5);backdrop-filter:blur(3px);z-index:100;display:none;align-items:flex-start;justify-content:center;padding:46px 20px;overflow-y:auto}
.modal-bg.show{display:flex}
.modal{background:var(--paper-2);max-width:620px;width:100%;box-shadow:var(--shadow-lg);border:1px solid var(--line-2);border-top:3px solid var(--yellow);animation:rise .3s both}
.modal .mh{padding:22px 24px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:12px}
.modal .mh h2{font-size:21px;flex:1}.modal .mh .x{cursor:pointer;color:var(--muted);font-size:24px;line-height:1}
.modal .mb{padding:24px}.modal .mf{padding:16px 24px;border-top:1px solid var(--line);display:flex;gap:10px;justify-content:flex-end}
.blueprint{background-image:linear-gradient(var(--line) 1px,transparent 1px),linear-gradient(90deg,var(--line) 1px,transparent 1px);background-size:26px 26px}

.lightbox-bg{position:fixed;inset:0;background:rgba(8,8,7,.94);z-index:200;display:none;align-items:center;justify-content:center;animation:lbFade .18s both}
.lightbox-bg.show{display:flex}
@keyframes lbFade{from{opacity:0}to{opacity:1}}
.lb-back{position:absolute;top:20px;left:20px;display:inline-flex;align-items:center;gap:7px;background:rgba(255,255,255,.08);color:#fff;border:1px solid rgba(255,255,255,.18);padding:9px 16px;font-size:13px;font-weight:600;cursor:pointer;transition:background .15s;z-index:2}
.lb-back:hover{background:rgba(255,255,255,.16)}
.lb-counter{position:absolute;top:24px;left:50%;transform:translateX(-50%);color:rgba(255,255,255,.65);font-size:12.5px;font-weight:600;letter-spacing:.02em;z-index:2}
.lb-close{position:absolute;top:20px;right:20px;width:38px;height:38px;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.08);color:#fff;border:1px solid rgba(255,255,255,.18);cursor:pointer;font-size:20px;line-height:1;transition:background .15s;z-index:2}
.lb-close:hover{background:rgba(255,255,255,.16)}
.lb-stage{position:relative;width:100%;height:100%;display:flex;align-items:center;justify-content:center;padding:90px 90px 70px}
.lb-img{max-width:100%;max-height:100%;object-fit:contain;box-shadow:0 30px 80px rgba(0,0,0,.5);animation:lbPop .22s cubic-bezier(.2,.8,.3,1.1) both}
@keyframes lbPop{from{opacity:0;transform:scale(.97)}to{opacity:1;transform:scale(1)}}
.lb-arrow{position:absolute;top:50%;transform:translateY(-50%);width:52px;height:52px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.08);color:#fff;border:1px solid rgba(255,255,255,.18);cursor:pointer;transition:background .15s,transform .15s;z-index:2}
