@media(max-width:640px){.lb-stage{padding:80px 18px 60px}.lb-arrow{width:42px;height:42px}.lb-arrow.prev{left:8px}.lb-arrow.next{right:8px}.lb-back{font-size:12px;padding:8px 12px}}

/* HOME */
.home-top{display:flex;justify-content:space-between;align-items:flex-end;gap:30px;padding-bottom:22px;margin-bottom:26px;border-bottom:2px solid var(--ink);position:relative;flex-wrap:wrap}
.home-top::after{content:"";position:absolute;left:0;bottom:-2px;width:84px;height:2px;background:var(--yellow);color:var(--on-yellow)}
.ht-greet{font-size:19px;color:var(--muted);font-weight:500}
.ht-name{font-size:46px;font-weight:700;letter-spacing:-.04em;line-height:.92;margin-top:4px}
.ht-clock{border:1px solid var(--line-2);padding:14px 18px;min-width:210px;background:var(--paper-2);display:flex;gap:26px}
.htc-k{font-size:10px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);font-weight:700}
.htc-v{font-size:23px;font-weight:700;margin-top:3px;letter-spacing:-.02em}.htc-v.mono{font-family:var(--mono);font-weight:500}

.ql{display:grid;grid-template-columns:repeat(6,1fr);border:1px solid var(--line);background:var(--paper-2);margin-bottom:8px}
