.ql-tile::before{content:"";position:absolute;top:0;left:0;right:0;height:2px;background:var(--yellow);transform:scaleX(0);transform-origin:left;transition:.18s;color:var(--on-yellow)}
.ql-tile:hover{background:var(--paper)}.ql-tile:hover::before{transform:scaleX(1)}
.ql-ic{margin-bottom:12px;color:var(--ink)}.ql-ic svg{width:21px;height:21px;stroke-width:1.6}
.ql-t{font-weight:700;font-size:13.5px;letter-spacing:-.01em}.ql-s{font-size:11px;color:var(--muted)}

.sec-head{display:flex;align-items:baseline;justify-content:space-between;margin:36px 0 15px;border-bottom:1px solid var(--line);padding-bottom:9px}
.sec-head h2{font-size:14px;font-weight:700;text-transform:uppercase;letter-spacing:.12em}
.sec-head .lk{font-size:12px;color:var(--muted);cursor:pointer;font-weight:600}.sec-head .lk:hover{color:var(--ink)}

.home-row{display:grid;grid-template-columns:1.65fr 1fr;gap:22px;align-items:start}
.carousel{position:relative;border:1px solid var(--line);overflow:hidden;background:var(--bed)}
.slide{position:relative;height:330px;display:flex;flex-direction:column;justify-content:flex-end;padding:24px}
.slide::after{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px);background-size:26px 26px}
.slide .tag{position:absolute;top:18px;left:18px;z-index:2;background:var(--yellow);color:var(--on-yellow);font-size:10.5px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;padding:5px 10px}
.slide .st{position:absolute;top:18px;right:18px;z-index:2}
.slide-t{position:relative;z-index:2;color:#fff;font-size:27px;font-weight:700;letter-spacing:-.02em;max-width:80%}
.slide-loc{position:relative;z-index:2;color:#d6d6cc;font-size:13px;margin-top:7px;display:flex;align-items:center;gap:6px}
.slide-meta{position:relative;z-index:2;display:flex;gap:22px;margin-top:14px;color:#fff;font-size:12.5px}
.slide-meta b{color:var(--yellow)}
.carousel .arr{position:absolute;top:50%;transform:translateY(-50%);z-index:3;width:38px;height:38px;background:rgba(0,0,0,.35);color:#fff;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(4px);border:1px solid rgba(255,255,255,.2)}
.carousel .arr:hover{background:var(--yellow);color:var(--on-yellow)}
.carousel .arr.l{left:14px}.carousel .arr.r{right:14px}
.dots{position:absolute;bottom:16px;right:18px;z-index:3;display:flex;gap:6px}
.dots span{width:8px;height:8px;background:rgba(255,255,255,.4);cursor:pointer}.dots span.on{background:var(--yellow);width:22px;color:var(--on-yellow)}
.ev-card{border:1px solid var(--line);background:var(--paper-2);padding:6px 18px}

/* Equal-height home cards: the two columns stretch to match, the card fills its
   column, and the "+N more" link is pinned to the bottom so both cards end
   flush instead of one dangling shorter than the other. */
.home-row.eq{align-items:stretch}
.home-row.eq>section,.home-row.eq>aside{display:flex;flex-direction:column;min-width:0}
.home-row.eq .ev-card{flex:1;display:flex;flex-direction:column}
.card-more{margin-top:auto;padding:11px 2px 5px;border-top:1px solid var(--line);
  font-size:12.5px;font-weight:700;color:var(--muted);display:block;transition:color .13s}
.card-more:hover{color:var(--ink)}
.ev-card>.ev:last-of-type,.ev-card>.news-row:last-of-type{border-bottom:none}
.ev{display:flex;gap:14px;padding:14px 0;border-bottom:1px solid var(--line)}
.ev:last-child{border-bottom:none}
.ev-d{text-align:center;background:var(--ink);color:var(--paper-2);padding:6px 11px;min-width:50px;height:fit-content}
.ev-d.y{background:var(--yellow);color:var(--on-yellow)}
.ev-d .m{font-size:10px;font-weight:700;letter-spacing:.06em}.ev-d .n{font-size:19px;font-weight:700;line-height:1}
.ev-t{font-weight:700;font-size:14px}.ev-s{color:var(--muted);font-size:12px;margin-top:2px}

.split{display:grid;grid-template-columns:1.3fr 1fr;border:1px solid var(--line);background:var(--paper-2)}
.split-col{padding:22px}.split-col+.split-col{border-left:1px solid var(--line)}
.trio{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-top:14px}
.ag{display:flex;gap:14px;padding:11px 0;border-bottom:1px solid var(--line)}.ag:last-child{border-bottom:none}
/* Wide enough for a whole slot — "11:45 – 12:45" — on one line. At 44px it fit
   a start time and nothing else, so an end time would have wrapped under it. */
.ag-t{font-family:var(--mono);font-weight:500;font-size:12.5px;min-width:96px;
  white-space:nowrap;color:var(--muted)}
.ag.y .ag-t{color:var(--ink)}
.ag-b{border-left:3px solid var(--line-2);padding-left:12px}.ag.y .ag-b{border-left-color:var(--yellow)}
.ag-b .t{font-weight:700;font-size:13.5px}.ag-b .s{color:var(--muted);font-size:12px}
.appr{display:flex;align-items:center;gap:10px;padding:11px 0;border-bottom:1px solid var(--line)}
.appr:last-of-type{border-bottom:none}
/* A bare `.cert` component lived here — a progress bar with a .top and a .bar —
   and nothing has used it for a long time: no template carries `class="cert"` on
   its own, and none carries its .top or .bar children. What it still did was
   collide. `cert` survives as a modifier on two other components, .tqr-row cert
   and .tk-praise cert, so a 13px bottom margin meant for a dead widget was
   landing on the recognition row and on the feed's certification card. That is
   the whole reason one row in the homepage list looked taller than its
   neighbours: the row was 58px like all the others, with 13px of somebody
   else's margin under it. Deleted rather than overridden — a defensive reset
   would leave the trap for the next component that wants to call itself cert. */

/* tiles / profiles */
.tiles{display:grid;gap:14px}
.tile{border:1px solid var(--line);background:var(--paper-2);padding:18px;cursor:pointer;transition:.16s}
.tile:hover{border-color:var(--ink);box-shadow:4px 4px 0 var(--yellow)}
.tile .ic{width:42px;height:42px;background:var(--paper-3);display:flex;align-items:center;justify-content:center;margin-bottom:13px}
.tile:hover .ic{background:var(--yellow);color:var(--on-yellow)}
.tile h4{font-size:15px;font-weight:700}.tile p{margin:3px 0 0;font-size:12.5px;color:var(--muted)}
.pcard{display:flex;align-items:center;gap:13px;padding:13px;border:1px solid var(--line);background:var(--paper-2);cursor:pointer;transition:.14s}
.pcard:hover{border-color:var(--ink);background:var(--paper)}
.pcard .av{width:44px;height:44px;background:var(--disc);color:var(--yellow);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:15px;flex:none}
.pcard .nm{font-weight:700;font-size:14px;line-height:1.15}
.pcard .po{font-size:12px;color:var(--muted);margin-top:1px}
.prof-h{display:flex;gap:18px;align-items:center;margin-bottom:18px}
.prof-h .av{width:72px;height:72px;background:var(--disc);color:var(--yellow);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:26px;flex:none}
.prof-row{display:flex;padding:10px 0;border-bottom:1px solid var(--line);font-size:14px}
.prof-row .k{width:130px;color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.05em;font-weight:700;flex:none}
.statc{border:1px solid var(--line);background:var(--paper-2);padding:20px}
.statc .v{font-size:30px;font-weight:700;letter-spacing:-.02em;margin:5px 0 2px}

@media(max-width:1080px){.tnav,.search{display:none}.menu-btn{display:flex}.ql{grid-template-columns:repeat(3,1fr)}}
@media(max-width:900px){.home-row{grid-template-columns:1fr}.split{grid-template-columns:1fr}.split-col+.split-col{border-left:none;border-top:1px solid var(--line)}.trio{grid-template-columns:1fr}.row.c2,.row.c3{grid-template-columns:1fr}.ht-name{font-size:34px}}
@media(max-width:560px){.ql{grid-template-columns:repeat(2,1fr)}
  /* The nav row overflowed by ~14px at 390px, scrolling the whole page
     sideways. Tightening the gaps reclaims ~34px; nothing is hidden, so
     Logout stays reachable (the mobile menu is built from NAV_ITEMS and does
     not include it). */
  .topnav-in{gap:4px;padding:0 8px}
  .tnav-right{gap:6px}
}

.avatar,.pcard .av,.prof-h .av{border-radius:50%}
.user{border-radius:0;padding:5px 14px 5px 6px;gap:10px;border-color:var(--line-2)}
.ht-clock{display:block;min-width:200px}
.htc-loc{margin-top:10px;padding-top:10px;border-top:1px solid var(--line);font-size:13px;color:var(--ink-2);font-weight:600;display:flex;align-items:center;gap:6px}
.htc-loc svg{color:var(--ink-2)}

.user{padding:0;border:none;background:none;display:flex;align-items:center;justify-content:center}
.user .avatar{width:38px;height:38px;border-radius:50%;background:var(--disc);color:#fff;font-weight:600;font-size:13px;transition:.15s}
.user:hover .avatar{box-shadow:0 0 0 3px var(--paper-3)}
.slide-tags{position:absolute;top:18px;left:18px;z-index:2;display:flex;gap:8px}
.slide-tags .tag{position:static}
.divchip{background:var(--ink);color:var(--paper-2);border:1px solid rgba(255,255,255,.28);font-size:10.5px;font-weight:700;letter-spacing:.05em;padding:4px 9px}

.pill,.pill.ok,.pill.warn,.pill.info,.pill.bad,.pill.mut{background:var(--paper-3);color:var(--ink);border:1px solid var(--line-2)}
.dot{background:var(--yellow);box-shadow:0 0 0 3px rgba(252,215,0,.22);color:var(--on-yellow)}
.step.done .ball{background:var(--ink);border-color:var(--ink);color:var(--paper-2)}
.step.done::before,.step.active::before{background:var(--ink)}
[id^="ob-"],#pc-voice{scroll-margin-top:84px}

body{background-color:var(--paper);background-image:radial-gradient(900px 480px at 82% -140px,rgba(252,215,0,.06),transparent);background-attachment:fixed}
.topnav{border-top:3px solid var(--yellow)}
.card{box-shadow:0 1px 2px rgba(18,18,16,.035),0 14px 30px -20px rgba(18,18,16,.14)}
.sec-head h2{display:inline-block}
.sec-head h2::before{content:"";display:inline-block;width:9px;height:9px;background:var(--yellow);margin-right:11px;vertical-align:baseline;color:var(--on-yellow)}
.page-head{overflow:hidden}

.btile{display:flex;align-items:center;gap:13px;padding:15px;border:1px solid var(--line);background:var(--paper-2);cursor:pointer;transition:.15s;width:100%}
.btile:hover{border-color:var(--ink);box-shadow:4px 4px 0 var(--yellow)}
.btile-ic{width:42px;height:42px;background:var(--paper-3);display:flex;align-items:center;justify-content:center;flex:none;transition:.15s}
.btile:hover .btile-ic{background:var(--yellow);color:var(--on-yellow)}
.kc{text-transform:none!important}

.booth-wall{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:16px}
.booth-card{position:relative;height:190px;cursor:pointer;overflow:hidden;display:flex;flex-direction:column;justify-content:flex-end;padding:16px;transition:transform .15s,box-shadow .15s;border:1px solid rgba(255,255,255,.08);background-size:cover;background-position:center}
.booth-card:hover{transform:translateY(-3px);box-shadow:6px 6px 0 var(--yellow)}
.booth-tag{position:absolute;top:12px;left:14px;background:var(--yellow);color:var(--on-yellow);font-size:10.5px;font-weight:800;letter-spacing:.04em;text-transform:uppercase;padding:4px 9px}
.booth-count{position:absolute;top:12px;right:14px;display:flex;align-items:center;gap:5px;background:rgba(0,0,0,.35);color:#fff;font-size:11px;font-weight:700;padding:4px 9px}
.booth-info{color:#fff}
.booth-name{font-weight:700;font-size:15.5px;letter-spacing:-.01em;line-height:1.2}
.booth-period{font-size:11.5px;color:rgba(255,255,255,.6);font-weight:600;margin-top:3px}
.booth-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(110px,1fr));gap:8px}
.booth-thumb{aspect-ratio:1;background-size:cover;background-position:center;cursor:pointer;border:1px solid var(--line);transition:transform .12s,box-shadow .12s}
.booth-thumb.ph{image-rendering:pixelated;filter:saturate(.75) contrast(.95)}
.booth-thumb:hover{transform:scale(1.04);box-shadow:3px 3px 0 var(--yellow);z-index:1}
.slide-wm{position:absolute;right:18px;bottom:12px;z-index:1;font-weight:700;font-size:78px;letter-spacing:-.05em;color:rgba(255,255,255,.06);line-height:.8;pointer-events:none}

/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ JOB REQUISITION ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â searchable department combo ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.jr-combo{position:relative}
.jr-combo-list{display:none;position:absolute;top:100%;left:0;right:0;margin-top:4px;background:var(--paper-2);border:1px solid var(--line-2);max-height:220px;overflow-y:auto;z-index:20;box-shadow:0 10px 30px rgba(18,18,16,.12)}
.jr-combo-list.show{display:block}
.jr-combo-item{padding:10px 12px;font-size:13.5px;cursor:pointer;border-bottom:1px solid var(--line)}
.jr-combo-item:last-child{border-bottom:none}
.jr-combo-item:hover{background:var(--paper)}
.jr-combo-empty{padding:12px;font-size:13px;color:var(--muted);text-align:center}
.field input:disabled,.field select:disabled{background:var(--paper-3);color:var(--muted-2);cursor:not-allowed}

/* ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
   ACCESSIBILITY BASELINE
   Added in the UI/UX audit. The stylesheet sets outline:none in nine places,
   which left keyboard users with no visible focus anywhere in the Hub. These
   rules restore it for keyboard navigation only, so mouse users see no change.
   ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â */
/* This drew the black box. It put a 2px near-black outline on every focused
   link, button and field on the Hub — square-cornered, sitting inside whatever
   rounded shape the control had, and !important so nothing could soften it.
   Removed at the owner's explicit and repeated instruction: no focus boxes.
   The cost, recorded here rather than argued about: nothing now shows which
   control has the keyboard. Tabbing through a form or a menu gives no feedback,
   which affects keyboard and assistive-technology users most. Restoring it is
   this one rule — put the outline declaration back and every control has its
   indicator again. */
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,
textarea:focus-visible,summary:focus-visible,details:focus-visible,
[tabindex]:focus-visible,[role="button"]:focus-visible{
  outline:none!important}
/* On dark surfaces the ink ring disappears, so switch to the yellow accent. */
.topnav .btn.y:focus-visible,.slide a:focus-visible,.booth-card:focus-visible,
.cf-ticket-head :focus-visible,.aw-user:focus-visible{
  outline:2px solid var(--yellow)!important;outline-offset:2px}

/* Skip link ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â first tab stop, hidden until focused. Clipped rather than pushed
   to left:-9999px, which would widen the document and cause a sideways scroll. */
.skip-link{position:absolute;width:1px;height:1px;overflow:hidden;
  clip-path:inset(50%);white-space:nowrap;z-index:1400;background:var(--ink);
  color:#fff;padding:0;font-size:13px;font-weight:700;text-decoration:none}
.skip-link:focus{position:fixed;left:8px;top:8px;width:auto;height:auto;
  overflow:visible;clip-path:none;padding:10px 16px}

/* Respect a reduced-motion preference: this session added transforms, slides
   and hover lifts throughout, none of which were opt-out before. */
@media(prefers-reduced-motion:reduce){
  *,*::before,*::after{
    animation-duration:.001ms!important;animation-iteration-count:1!important;
    transition-duration:.001ms!important;scroll-behavior:auto!important}
  .nx-card:hover,.hrf-card:hover,.btile:hover,.tl-row:hover{transform:none!important}
}

/* ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â SHARED FORM CONTROL ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
   Six near-identical input classes were created across this session
   (.nf-in .sf-in .if-in .hf-in .td-in .trm-in). This is the single definition
   new forms should use; the duplicates remain until each form is migrated. */
.fld{margin-bottom:15px}
.fld>label{display:block;font-size:10.5px;font-weight:700;text-transform:uppercase;
  letter-spacing:.09em;color:var(--muted);margin-bottom:5px}
.inp{width:100%;border:1px solid var(--line-2);padding:10px 12px;font-family:inherit;
  font-size:14px;outline:none;background:var(--paper-2);transition:border-color .13s}
.inp:focus{border-color:var(--ink)}
.inp.bad{border-color:var(--bad);background:var(--bad-bg)}
.fld-err{font-size:12px;color:var(--bad);font-weight:600;margin-top:5px}
.fld-hint{font-size:12px;color:var(--muted);margin-top:5px}

/* ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â SHARED OVERLAY / DIALOG ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â
   Consolidates the .cm-bg / .wa-bg / .tr-bg / .evm-bg pattern. */
.ovl{position:fixed;inset:0;background:rgba(18,18,16,.5);z-index:900;display:none}
.ovl.on{display:block}
.dlg{position:fixed;z-index:901;top:50%;left:50%;transform:translate(-50%,-50%);
  width:min(760px,94vw);max-height:90vh;overflow-y:auto;background:var(--paper-2);
  border:1px solid var(--line-2);box-shadow:0 22px 60px -20px rgba(18,18,16,.5);
  padding:24px;display:none}
.dlg.on{display:block}
.dlg-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:16px}
.dlg-head h3{font-size:19px;letter-spacing:-.02em;margin:0 0 4px}
.dlg-x{background:none;border:none;font-size:22px;line-height:1;color:var(--muted);
  cursor:pointer;font-family:inherit;padding:0 4px}
