.cmsbar{position:fixed;left:20px;bottom:20px;z-index:820;font-family:var(--sans)}
.cmsbar-tab{display:inline-flex;align-items:center;gap:8px;background:var(--ink);color:var(--paper-2);
  border:none;font-family:inherit;font-size:12.5px;font-weight:700;letter-spacing:.03em;
  padding:11px 16px;cursor:pointer;box-shadow:0 14px 34px -16px rgba(18,18,16,.5);
  transition:transform .15s,background .15s}
.cmsbar-tab:hover{transform:translateY(-2px);background:#000}
.cmsbar-tab svg{width:15px;height:15px;color:var(--yellow)}
.cmsbar-tab b{background:var(--yellow);color:var(--on-yellow);font-size:10.5px;font-weight:800;
  padding:1px 6px;margin-left:2px}

.cmsbar-body{display:none;position:absolute;left:0;bottom:calc(100% + 10px);
  width:min(290px,calc(100vw - 40px));background:var(--paper-2);border:1px solid var(--line-2);
  box-shadow:0 22px 60px -22px rgba(18,18,16,.45);padding:14px}
.cmsbar.open .cmsbar-body{display:block}
.cmsbar-head{padding-bottom:11px;margin-bottom:11px;border-bottom:1px solid var(--line)}
.cmsbar-name{display:block;font-weight:700;font-size:13.5px;letter-spacing:-.01em}
.cmsbar-state{display:block;font-size:11px;font-weight:600;letter-spacing:.05em;
  text-transform:uppercase;color:var(--muted);margin-top:3px}
.cmsbar-note{font-size:12px;color:var(--muted);line-height:1.5;margin:0 0 11px}
.cmsbar-btn{display:block;width:100%;text-align:center;padding:9px 12px;margin-bottom:7px;
  border:1px solid var(--line-2);background:var(--paper-2);font-size:12.5px;font-weight:700;
  color:var(--ink);text-decoration:none;font-family:inherit;cursor:pointer;transition:.13s}
.cmsbar-btn:hover{border-color:var(--ink);box-shadow:3px 3px 0 var(--yellow)}
.cmsbar-btn.primary{background:var(--yellow);border-color:var(--yellow);color:var(--on-yellow)}
.cmsbar-btn.primary:hover{box-shadow:3px 3px 0 var(--ink)}
.cmsbar-btn.ghost{background:none;border-color:transparent;color:var(--muted);
  text-decoration:underline;margin-bottom:0}
.cmsbar-btn.ghost:hover{color:var(--ink);box-shadow:none}
.cmsbar form{margin:0}
@media(max-width:620px){.cmsbar{left:12px;bottom:12px}}

/* ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â SKELETON ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â Placeholder for content that loads after paint. */
.skel{background:linear-gradient(90deg,var(--paper-3) 25%,var(--paper) 37%,var(--paper-3) 63%);
  background-size:400% 100%;animation:skel 1.3s ease-in-out infinite}
@keyframes skel{0%{background-position:100% 50%}100%{background-position:0 50%}}

