.ed-on .cms-block{position:relative}
.ed-on .cms-block::after{content:"";position:absolute;inset:-6px;border:1px dashed transparent;
  pointer-events:none;transition:border-color .12s}
.ed-on .cms-block:hover::after{border-color:var(--line-2)}
.ed-on .cms-block.ed-sel::after{border:2px solid var(--yellow-deep);border-style:solid}

/* Hover toolbar. Sits above the block and is the only affordance shown until
   a block is selected, so reading the page in edit mode stays legible. */
.ed-bar{position:absolute;top:-15px;right:0;z-index:40;display:none;gap:1px;
  background:var(--raised);padding:2px;box-shadow:var(--shadow)}
.ed-on .cms-block:hover>.ed-bar,.ed-on .cms-block.ed-sel>.ed-bar{display:flex}
.ed-bar button{width:27px;height:25px;border:none;background:transparent;color:var(--raised-fg);cursor:pointer;
  display:flex;align-items:center;justify-content:center;padding:0}
.ed-bar button:hover{background:var(--yellow);color:var(--on-yellow)}
.ed-bar button[disabled]{opacity:.32;cursor:default}
.ed-bar button[disabled]:hover{background:transparent;color:#fff}
.ed-bar .ed-grip{cursor:grab}
.ed-bar .ed-lbl{color:var(--raised-fg);font-size:10px;font-weight:700;text-transform:uppercase;
  letter-spacing:.08em;padding:0 var(--sp-2);display:flex;align-items:center;white-space:nowrap}

/* Drag and drop */
.ed-on .cms-block.ed-drag{opacity:.4}
.ed-drop{height:3px;background:var(--yellow);margin:var(--sp-1) 0;display:none;color:var(--on-yellow)}
.ed-drop.on{display:block}
/* An empty column keeps a height so it stays a drop target. There is no
   :empty placeholder because a column in edit mode always contains its
   "+ Add a block" button, so :empty could never match. */
.ed-on .cms-col{min-height:74px}
.ed-on .cms-col.ed-over{outline:2px dashed var(--yellow-deep);outline-offset:3px}

/* Inline text editing */
.ed-on [data-ed-field]{outline:none;transition:background .12s}
.ed-on [data-ed-field]:hover{background:rgba(252,215,0,.16)}
.ed-on [data-ed-field]:focus{background:rgba(252,215,0,.28);box-shadow:0 0 0 2px var(--yellow-deep)}
.ed-dirty{position:fixed;left:50%;transform:translateX(-50%);bottom:18px;z-index:1200;
  background:var(--ink);color:var(--paper-2);font-size:12.5px;font-weight:600;padding:var(--sp-3) var(--sp-5);
  display:none;align-items:center;gap:var(--sp-4);box-shadow:var(--shadow-lg)}
.ed-dirty.on{display:flex}
.ed-dirty button{font-size:12px;font-weight:700;padding:6px 13px;border:none;cursor:pointer;
  background:var(--yellow);color:var(--on-yellow)}

/* Add-block palette */
.ed-add{display:none;width:100%;padding:var(--sp-3);border:1px dashed var(--line-2);
  background:transparent;color:var(--muted);font-size:12.5px;font-weight:700;cursor:pointer;
  font-family:inherit}
.ed-on .ed-add{display:block}
.ed-add:hover{border-color:var(--yellow-deep);color:var(--ink);background:rgba(252,215,0,.1)}
.ed-pal{position:fixed;inset:0;z-index:1300;background:rgba(18,18,16,.55);
  display:none;align-items:flex-start;justify-content:center;padding:var(--sp-7) var(--sp-4);
  overflow:auto}
.ed-pal.on{display:flex}
.ed-pal-in{background:var(--paper);width:min(880px,100%);border:1px solid var(--line-2);
  box-shadow:var(--shadow-lg)}
.ed-pal-hd{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-4);
  padding:var(--sp-5);border-bottom:1px solid var(--line)}
.ed-pal-hd h3{font-size:15px;font-weight:700;letter-spacing:-.01em}
.ed-pal-gr{padding:var(--sp-5);display:grid;grid-template-columns:repeat(auto-fill,minmax(184px,1fr));
  gap:var(--sp-3)}
.ed-pal-b{text-align:left;border:1px solid var(--line);background:var(--paper-2);padding:var(--sp-4);
  cursor:pointer;font-family:inherit;transition:.13s}
.ed-pal-b:hover{border-color:var(--yellow-deep);background:var(--paper-2);transform:translateY(-1px)}
.ed-pal-b b{display:block;font-size:13px;font-weight:700;margin-bottom:3px}
.ed-pal-b span{display:block;font-size:11.5px;color:var(--muted);line-height:1.45}
.ed-pal-sec{grid-column:1/-1;font-size:10.5px;font-weight:700;text-transform:uppercase;
  letter-spacing:.1em;color:var(--muted);padding-top:var(--sp-2)}

/* Settings drawer */
.ed-drawer{position:fixed;top:0;right:0;bottom:0;width:min(370px,100vw);z-index:1250;
  background:var(--paper-2);border-left:1px solid var(--line-2);box-shadow:var(--shadow-lg);
  transform:translateX(100%);transition:transform .2s;display:flex;flex-direction:column}
.ed-drawer.on{transform:none}
.ed-dr-hd{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);
  padding:var(--sp-4) var(--sp-5);border-bottom:1px solid var(--line)}
.ed-dr-hd b{font-size:13.5px}
.ed-dr-bd{padding:var(--sp-5);overflow:auto;flex:1;display:flex;flex-direction:column;gap:var(--sp-4)}
.ed-f{display:block}
.ed-f>span{display:block;font-size:10.5px;font-weight:700;text-transform:uppercase;
  letter-spacing:.08em;color:var(--muted);margin-bottom:var(--sp-2)}
.ed-f input,.ed-f select,.ed-f textarea{width:100%;font-family:inherit;font-size:13px;
  padding:var(--sp-2) 10px;border:1px solid var(--line-2);background:var(--paper);color:var(--ink)}
.ed-f input:focus,.ed-f select:focus,.ed-f textarea:focus{outline:2px solid var(--ink);outline-offset:-2px}
.ed-lay{display:grid;grid-template-columns:repeat(auto-fill,minmax(78px,1fr));gap:var(--sp-2)}
.ed-lay button{border:1px solid var(--line-2);background:var(--paper);cursor:pointer;padding:var(--sp-2);
  font-family:inherit;font-size:10px;font-weight:700;color:var(--muted)}
.ed-lay button.on{border-color:var(--ink);background:var(--ink);color:var(--paper-2)}
.ed-lay i{display:grid;gap:2px;height:15px;margin-bottom:var(--sp-1)}
.ed-lay i s{background:var(--line-2);display:block;height:100%}
.ed-lay button.on i s{background:var(--yellow);color:var(--on-yellow)}

@media(prefers-reduced-motion:reduce){
  .ed-drawer{transition:none}
  .ed-pal-b:hover{transform:none}
}

/* The agenda block reuses .split, which is a two-column grid globally. With one
   column of content that left half the card empty, so a single-column variant is
   declared explicitly rather than relying on the page overriding it. */
.split.one{grid-template-columns:1fr}

/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Icon picker ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
   One chooser used by every icon field on the Hub. Styled here rather than in
   each template so a new form gets it for free. */
.ip-head{display:flex;gap:var(--sp-2);align-items:center;margin-bottom:var(--sp-3)}
.ip-head .inp{flex:1}
/* A rail of categories beside the grid: 1,512 icons in one alphabetical wall is
   not something anyone browses, so the set is entered by subject or by search. */
.ip-dlg{max-width:880px}
.ip-body{display:grid;grid-template-columns:186px 1fr;gap:var(--sp-3);align-items:start}
.ip-rail{display:flex;flex-direction:column;gap:1px;max-height:54vh;overflow:auto;
  border:1px solid var(--line);background:var(--paper-2);padding:3px}
.ip-cat{display:flex;align-items:center;justify-content:space-between;gap:6px;
  border:0;background:transparent;font-family:inherit;font-size:12px;text-align:left;
  padding:6px 8px;cursor:pointer;color:var(--ink-2);line-height:1.35}
.ip-cat:hover{background:var(--paper-2);color:var(--ink)}
.ip-cat.on{background:var(--disc);color:var(--yellow);font-weight:700}
.ip-cat i{font-style:normal;font-size:10px;opacity:.55;flex:none;font-variant-numeric:tabular-nums}
.ip-results{min-width:0}
.ip-results[aria-busy="true"]{opacity:.5}
.ip-count{font-size:11.5px;color:var(--ink-2);margin-bottom:var(--sp-2)}
.ip-none{grid-column:1/-1;font-size:12.5px;color:var(--muted);margin:0;padding:var(--sp-4) 0}
.ip-foot{font-size:10.5px;margin:var(--sp-3) 0 0;line-height:1.5}
.ip-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(88px,1fr));
  gap:var(--sp-2);max-height:52vh;overflow:auto;padding:2px}
/* On a phone the rail sits above the grid rather than squeezing it to nothing. */
@media(max-width:720px){
  .ip-body{grid-template-columns:1fr}
  .ip-rail{flex-direction:row;overflow-x:auto;max-height:none}
  .ip-cat{white-space:nowrap}
  .ip-cat i{display:none}
}
.ip-cell{border:1px solid var(--line);background:var(--paper-2);padding:var(--sp-3) var(--sp-1);
  cursor:pointer;font-family:inherit;text-align:center;transition:.12s}
.ip-cell:hover{border-color:var(--yellow-deep);background:var(--paper-2)}
.ip-cell.on{border-color:var(--disc);background:var(--disc);color:var(--yellow)}
.ip-cell svg{display:block;margin:0 auto var(--sp-1)}
.ip-cell span{display:block;font-size:9.5px;color:var(--muted);word-break:break-all;line-height:1.3}
.ip-cell.on span{color:rgba(255,255,255,.62)}
/* The chosen icon shown beside its field, so the stored name is not the only cue. */
/* A "choose an icon / a picture" field: thumbnail, then the field, then a clear
   button that only shows when there is something to clear.

   Both pickers used to append a bare box *after* their input. The field label is
   a block and the input is full width, so that box landed on its own line
   underneath as a stray white square ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â and printed the word "none" inside
   itself when empty. */
.pick{display:flex;align-items:stretch;gap:0;border:1px solid var(--line-2);
  background:var(--paper-2);min-width:0}
.pick:focus-within{border-color:var(--ink)}
.pick>input{flex:1;min-width:0;border:0!important;background:transparent!important;
  padding:8px 10px;font-family:inherit;font-size:13px;outline:none;cursor:pointer}
.pick-prev{flex:none;width:38px;border:0;border-right:1px solid var(--line);
  background:var(--paper-2);display:flex;align-items:center;justify-content:center;
  cursor:pointer;color:var(--ink-2);padding:0;overflow:hidden}
.pick-prev:hover{background:var(--paper-3)}
.pick-prev svg,.pick-prev img{display:block}
.pick-media .pick-prev{width:52px}
.pick-media .pick-prev img{width:100%;height:100%;object-fit:cover}
/* Empty: a dashed hint drawn in CSS, rather than the word "none" in a box. */
.pick.is-empty .pick-prev{background:repeating-linear-gradient(45deg,
  var(--paper-2) 0 5px,var(--paper-3) 5px 10px)}
.pick.is-empty .pick-prev::after{content:"+";font-size:15px;font-weight:700;
  color:var(--muted-2);line-height:1}
.pick.is-empty .pick-prev:has(svg)::after,
.pick.is-empty .pick-prev:has(img)::after{content:none}
.pick-clear{flex:none;width:30px;border:0;border-left:1px solid var(--line);
  background:transparent;cursor:pointer;font-size:16px;line-height:1;
  color:var(--muted);font-family:inherit}
.pick-clear:hover{color:var(--bad);background:var(--paper-2)}
/* Nothing chosen means nothing to clear. */
.pick.is-empty .pick-clear{display:none}

