.cf-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:22px;align-items:start;max-width:100%}
.cf-layout>*{min-width:0}
.cf-toolbar{display:flex;gap:10px;align-items:center;margin-bottom:14px;flex-wrap:wrap}
.cf-search{flex:1;min-width:200px;display:flex;align-items:center;gap:8px;background:var(--paper-2);border:1px solid var(--line);padding:9px 14px}
.cf-search input{border:none;outline:none;background:none;font-family:inherit;font-size:13.5px;width:100%}
.cf-chips{display:flex;gap:8px;overflow-x:auto;padding-bottom:6px;margin-bottom:16px;scrollbar-width:thin}
.cf-chip{flex:none;border:1px solid var(--line-2);background:var(--paper-2);padding:8px 16px;font-family:inherit;font-weight:700;font-size:12.5px;cursor:pointer;white-space:nowrap;transition:all .12s}
.cf-chip:hover{border-color:var(--ink)}
.cf-chip.on{background:var(--ink);color:var(--paper-2);border-color:var(--ink)}
.cf-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:16px}
.cf-card{background:var(--paper-2);border:1px solid var(--line);display:flex;flex-direction:column;transition:box-shadow .15s,transform .15s}
.cf-card:hover{box-shadow:0 10px 26px rgba(18,18,16,.10);transform:translateY(-2px)}
.cf-card img,.cf-card .noimg{width:100%;aspect-ratio:4/3;object-fit:cover;display:block;border-bottom:1px solid var(--line)}
.cf-card .noimg{background:var(--paper-3)}
.cf-body{padding:12px 14px 14px;display:flex;flex-direction:column;gap:6px;flex:1}
.cf-name{font-weight:800;font-size:13.5px;line-height:1.3}
.cf-desc{font-size:11.5px;color:var(--muted);line-height:1.45;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.cf-foot{display:flex;align-items:center;justify-content:space-between;margin-top:auto;padding-top:8px}
.cf-price{font-weight:800;font-size:13.5px}
.cf-price small{font-weight:600;color:var(--muted);font-size:10.5px}
.cf-add{border:2px solid var(--ink);background:var(--yellow);font-family:inherit;font-weight:800;font-size:12px;padding:6px 16px;cursor:pointer;transition:background .12s;color:var(--on-yellow)}
.cf-add:hover{background:var(--yellow-2);color:var(--on-yellow)}
.cf-step{display:none;align-items:center;gap:0;border:2px solid var(--ink)}
.cf-step button{border:none;background:var(--disc);color:var(--yellow);width:28px;height:28px;font-size:15px;font-weight:800;cursor:pointer;font-family:inherit}
.cf-step b{width:30px;text-align:center;font-size:13px}
.cf-card.in-cart .cf-add{display:none}
.cf-card.in-cart .cf-step{display:flex}
.cf-card.in-cart{outline:2px solid var(--yellow)}
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ order ticket ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.cf-ticket{background:var(--paper-2);border:1px solid var(--line);position:sticky;top:88px;box-shadow:0 8px 30px rgba(18,18,16,.06)}
.cf-ticket-head{background:var(--raised);color:var(--raised-fg);padding:14px 18px;display:flex;justify-content:space-between;align-items:center}
.cf-ticket-head b{font-size:13px;letter-spacing:.12em}
.cf-count{background:var(--yellow);color:var(--on-yellow);font-weight:800;font-size:11.5px;min-width:22px;height:22px;border-radius:11px;display:flex;align-items:center;justify-content:center;padding:0 7px}
.cf-lines{padding:8px 18px;max-height:300px;overflow-y:auto}
.cf-line{display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px dashed var(--line-2);font-size:12.5px}
.cf-line:last-child{border-bottom:none}
.cf-line .n{flex:1;min-width:0;font-weight:700}
.cf-line .n small{display:block;font-weight:600;color:var(--muted);font-size:10.5px}
.cf-line .qbtn{width:20px;height:20px;border:1px solid var(--line-2);background:var(--paper);cursor:pointer;font-family:inherit;font-weight:700;line-height:1}
.cf-line .amt{font-weight:800;white-space:nowrap;min-width:56px;text-align:right}
.cf-empty{padding:28px 18px;text-align:center;color:var(--muted);font-size:12.5px}
.cf-total{display:flex;justify-content:space-between;font-weight:800;font-size:14.5px;padding:12px 18px;border-top:2px solid var(--ink)}
.cf-fields{padding:0 18px 16px;display:flex;flex-direction:column;gap:8px}
.cf-fields input{padding:9px 12px;border:1px solid var(--line);background:var(--paper);font-family:inherit;font-size:12.5px}
.cf-place{margin:0 18px 18px;border:2px solid var(--ink);background:var(--yellow);font-family:inherit;font-weight:800;font-size:13.5px;padding:12px;cursor:pointer;transition:background .12s;color:var(--on-yellow)}
.cf-place:hover{background:var(--yellow-2);color:var(--on-yellow)}
.cf-place:disabled{opacity:.6;cursor:default}
@media(max-width:900px){.cf-layout{grid-template-columns:1fr}.cf-ticket{position:static}}

/* from content\_feature_calendar.html ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â 118 rules */
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ VIEW TOGGLE ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.cal-toggle{display:inline-flex;border:1px solid var(--line-2);overflow:hidden;margin-bottom:22px}
.cal-toggle-btn{padding:8px 18px;font-size:13px;font-weight:700;cursor:pointer;border:none;background:var(--paper-2);font-family:inherit;color:var(--muted);transition:background .13s,color .13s;text-decoration:none;display:inline-flex;align-items:center;gap:7px}
.cal-toggle-btn:hover{background:var(--paper-3);color:var(--ink)}
.cal-toggle-btn.active{background:var(--ink);color:var(--paper-2)}
/* ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â MONTH VIEW ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â */
.cal-layout{display:grid;grid-template-columns:1fr 300px;gap:22px;align-items:start}
.cal-card{background:var(--paper-2);border:1px solid var(--line);padding:22px}
.cal-nav{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}
.cal-month-title{font-size:21px;font-weight:700;letter-spacing:-.02em}
.cal-nav-btns{display:flex;gap:8px}
.cal-nav-btn{display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;border:1px solid var(--line-2);background:var(--paper-2);cursor:pointer;font-size:17px;font-weight:600;color:var(--ink);transition:background .13s,border-color .13s;text-decoration:none}
.cal-nav-btn:hover{background:var(--yellow);border-color:var(--yellow);color:var(--on-yellow)}
.cal-nav-today{padding:0 14px;font-size:13px;font-weight:700;white-space:nowrap;width:auto}
.cal-weekdays{display:grid;grid-template-columns:repeat(7,1fr);gap:6px;margin-bottom:6px}
.cal-weekday{text-align:center;font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;padding:4px 0}
.cal-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:6px}
.cal-day{min-height:74px;border:1px solid var(--line);padding:6px;background:var(--paper-2)}
.cal-day.today{background:var(--warn-bg)}
.cal-day.empty{border:1px solid transparent;background:transparent}
.cal-day-num{font-weight:600;font-size:13px;color:var(--ink)}
.cal-day.today .cal-day-num{font-weight:800}
.cal-ev-chip{font-size:10.5px;font-weight:600;margin-top:3px;padding:2px 5px;background:var(--paper-3);color:var(--ink);border-left:2px solid var(--yellow);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cal-ev-chip.ev-holiday{border-left-color:var(--ok);background:var(--ok-bg);color:var(--ok)}
.cal-ev-chip.ev-company{border-left-color:var(--info);background:var(--info-bg);color:var(--info)}
.cal-ev-chip.ev-training{border-left-color:var(--warn);background:var(--warn-bg);color:var(--warn)}
/* ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â WEEK VIEW ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â Same visual family as the month grid, one column per day. */
.wk-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px}
.wk-col{border:1px solid var(--line);background:var(--paper-2);display:flex;
  flex-direction:column;min-height:240px}
.wk-col.today{background:var(--warn-bg)}
.wk-col.off{background:var(--paper)}
.wk-head{padding:8px 9px 7px;border-bottom:1px solid var(--line);display:flex;
  align-items:baseline;justify-content:space-between;gap:6px}
.wk-wd{font-size:9.5px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}
.wk-num{font-size:15px;font-weight:700;letter-spacing:-.01em}
.wk-col.today .wk-num{font-weight:800}
.wk-col.off .wk-num{color:var(--muted)}
.wk-body{padding:7px;display:flex;flex-direction:column;gap:5px;flex:1}
.wk-ev{display:flex;flex-direction:column;gap:1px;padding:5px 7px;background:var(--paper-3);
  border-left:2px solid var(--yellow);font-size:11px;line-height:1.3}
.wk-ev-t{font-weight:700;font-size:9.5px;text-transform:uppercase;letter-spacing:.05em;opacity:.85}
.wk-ev-n{font-weight:600;overflow:hidden;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical}
.wk-ev.ev-holiday{border-left-color:var(--ok);background:var(--ok-bg);color:var(--ok)}
.wk-ev.ev-company{border-left-color:var(--info);background:var(--info-bg);color:var(--info)}
.wk-ev.ev-training{border-left-color:var(--warn);background:var(--warn-bg);color:var(--warn)}
.wk-ev.ev-remote_session{border-left-color:var(--violet);background:var(--violet-bg);color:var(--violet)}
.wk-ev.ev-online_meeting{border-left-color:var(--sky);background:var(--sky-bg);color:var(--sky)}
.wk-ev.ev-town_hall{border-left-color:var(--clay);background:var(--clay-bg);color:var(--clay)}
.wk-ev.ev-deadline{border-left-color:var(--bad);background:var(--bad-bg);color:var(--bad)}
.wk-none{color:var(--line-2);font-size:12px;text-align:center;padding:12px 0}
.wk-col.hr-editable{cursor:pointer}
.wk-col.hr-editable:hover{box-shadow:inset 0 0 0 2px var(--yellow)}
.wk-ev.hr-editable{cursor:pointer}
.wk-ev.hr-editable:hover{text-decoration:underline}
/* ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â YEAR VIEW ÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚ÂÃƒÂ¢Ã¢â‚¬Â¢Ã‚Â */
.year-wrap{width:100%}
.year-nav-row{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}
.year-title{font-size:32px;font-weight:700;letter-spacing:-.04em}
.year-legend{display:flex;gap:16px;flex-wrap:wrap;margin-bottom:20px}
.year-legend-item{display:flex;align-items:center;gap:7px;font-size:13px;font-weight:600;color:var(--ink-2)}
