.year-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
/* Mini month */
.mini-month{background:var(--paper-2);border:1px solid var(--line);padding:16px 14px}
.mini-month-name{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:var(--ink);margin-bottom:10px;cursor:pointer}
.mini-month-name:hover{color:var(--ink)}
.mini-weekdays{display:grid;grid-template-columns:repeat(7,1fr);margin-bottom:2px}
.mini-wd{text-align:center;font-size:9px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.04em;padding:3px 0}
.mini-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:1px}
.mini-day{min-height:24px;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:500;color:var(--ink-2);cursor:pointer;position:relative;transition:background .1s}
.mini-day:hover{background:var(--paper-3)}
.mini-day.empty{cursor:default;pointer-events:none;color:transparent}
.mini-day.today{background:var(--ink)!important;color:var(--paper-2)!important;font-weight:800}
.mini-day.has-ev-meeting{background:rgba(252,215,0,.55);color:var(--ink);font-weight:700}
.mini-day.has-ev-holiday{background:var(--ok-bg);color:var(--ok);font-weight:700}
.mini-day.has-ev-company{background:var(--info-bg);color:var(--info);font-weight:700}
.mini-day.has-ev-training{background:var(--warn-bg);color:var(--warn);font-weight:700}
.mini-day.has-ev-other{background:var(--paper-3);color:var(--ink);font-weight:700}
/* tooltip */
.mini-day[title]:hover::after{content:attr(title);
  position:absolute;bottom:calc(100% + 4px);left:50%;transform:translateX(-50%);
  background:var(--ink);color:var(--paper-2);font-size:10px;font-weight:600;padding:4px 8px;
  white-space:nowrap;z-index:50;pointer-events:none;
  box-shadow:0 4px 14px rgba(18,18,16,.22);letter-spacing:0}
