  font-size:14px;outline:none;background:var(--paper-2)}
.evm textarea{resize:vertical}
.evm .chk{display:flex;align-items:center;gap:8px;font-size:13.5px;text-transform:none;
  letter-spacing:0;color:var(--ink);font-weight:400;margin-bottom:13px}
.evm-actions{display:flex;gap:10px;align-items:center;margin-top:8px;padding-top:15px;
  border-top:1px solid var(--line)}
@media(max-width:900px){.wk-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:520px){.wk-grid{grid-template-columns:1fr}.wk-col{min-height:0}}
@media(max-width:1100px){.year-grid{grid-template-columns:repeat(3,1fr)}}
@media(max-width:820px){
  .cal-layout{grid-template-columns:1fr}
  .year-grid{grid-template-columns:repeat(2,1fr)}
  .cal-day{min-height:52px}
}
@media(max-width:500px){
  .year-grid{grid-template-columns:1fr}
  .cal-weekday,.mini-wd{font-size:8px}
}

