.nx-chip{display:inline-flex;align-items:center;gap:7px;padding:7px 14px;
  border:1px solid var(--line-2);background:var(--paper-2);font-family:inherit;
  font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;
  color:var(--ink-3);text-decoration:none;cursor:pointer;transition:.14s}
.nx-chip:hover{border-color:var(--ink);color:var(--ink);transform:translateY(-1px)}
.nx-chip.on{background:var(--ink);border-color:var(--ink);color:var(--paper-2)}
.nx-chip .n{font-size:10.5px;opacity:.6;font-weight:600}
.nx-chip.on .n{opacity:.75}
.nx-sort{margin-left:auto;display:flex;align-items:center;gap:8px}
.nx-sort select{border:1px solid var(--line-2);background:var(--paper-2);
  padding:8px 30px 8px 12px;font-family:inherit;font-size:12.5px;font-weight:600;
  outline:none;cursor:pointer;appearance:none;-webkit-appearance:none;min-width:150px;
  background-image:url("data:image/svg+xml,%3Csvg width='11' height='11' viewBox='0 0 24 24' fill='none' stroke='%2376756A' stroke-width='2' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='m6 9 6 6 6-6'/%3E%3C/svg%3E");
  background-repeat:no-repeat;background-position:right 10px center}
.nx-sort select:hover{border-color:var(--ink)}
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ feed ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.nx-feed{display:flex;flex-direction:column;gap:14px}
.nx-item{position:relative}
.nx-card{display:flex;gap:18px;background:var(--paper-2);border:1px solid var(--line);
  padding:18px 20px;text-decoration:none;color:inherit;position:relative;
  transition:box-shadow .18s cubic-bezier(.2,.8,.3,1),transform .18s cubic-bezier(.2,.8,.3,1),border-color .18s}
/* Yellow accent grows out of the left edge on hover. */
.nx-card::before{content:"";position:absolute;left:-1px;top:-1px;bottom:-1px;width:3px;
  background:var(--yellow);transform:scaleY(0);transform-origin:top;transition:transform .2s cubic-bezier(.2,.8,.3,1);color:var(--on-yellow)}
.nx-card:hover{transform:translateY(-2px);border-color:var(--line-2);
  box-shadow:0 2px 4px rgba(18,18,16,.03),0 18px 34px -24px rgba(18,18,16,.28)}
.nx-card:hover::before{transform:scaleY(1)}
.nx-thumb{flex:none;width:168px;aspect-ratio:16/9;overflow:hidden;background:var(--paper-3);
  border:1px solid var(--line)}
.nx-thumb img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .4s cubic-bezier(.2,.8,.3,1)}
.nx-card:hover .nx-thumb img{transform:scale(1.05)}
.nx-body{flex:1;min-width:0;display:flex;flex-direction:column}
.nx-top{display:flex;align-items:center;gap:8px;margin-bottom:9px;flex-wrap:wrap}
.nx-cat{font-size:10px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;
  padding:4px 9px;background:var(--disc);color:var(--yellow)}
.nx-tag{font-size:9.5px;font-weight:800;letter-spacing:.09em;text-transform:uppercase;padding:3px 8px}
.nx-tag.new{background:var(--yellow);color:var(--on-yellow)}
.nx-tag.pin{background:var(--info-bg);color:var(--info)}
.nx-tag.draft{background:var(--warn-bg);color:var(--warn)}
.nx-when{margin-left:auto;font-size:11.5px;color:var(--muted);font-weight:600;white-space:nowrap}
.nx-title{font-size:18.5px;font-weight:700;letter-spacing:-.022em;line-height:1.28;
  margin:0 0 7px;color:var(--ink)}
.nx-card:hover .nx-title{text-decoration:underline;text-underline-offset:3px;
  text-decoration-thickness:1.5px;text-decoration-color:var(--yellow)}
.nx-sum{font-size:13.5px;line-height:1.6;color:var(--muted);margin:0 0 14px;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
/* One compact line: who wrote it, then the numbers. Never a tall white bar. */
.nx-foot{display:flex;align-items:center;gap:9px;margin-top:auto;padding-top:12px;
  border-top:1px solid var(--line);font-size:12px;color:var(--muted);flex-wrap:wrap}
.nx-av{width:22px;height:22px;border-radius:50%;background:var(--disc);color:var(--yellow);
  display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:800;flex:none}
.nx-who{font-weight:700;color:var(--ink-2);white-space:nowrap}
.nx-sep{opacity:.4}
.nx-mx{display:inline-flex;align-items:center;gap:4px;white-space:nowrap}
.nx-mx svg{width:12px;height:12px;opacity:.65}
.nx-more{margin-left:auto;font-weight:800;font-size:11.5px;letter-spacing:.05em;
  text-transform:uppercase;color:var(--ink);display:inline-flex;align-items:center;gap:5px;
  white-space:nowrap}
.nx-card:hover .nx-more{color:var(--ink)}
.nx-more svg{width:12px;height:12px;transition:transform .18s}
.nx-card:hover .nx-more svg{transform:translateX(3px)}
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ lead card (first article, page 1) ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.nx-card.lead{flex-direction:column;gap:0;padding:0;overflow:hidden}
.nx-card.lead .nx-thumb{width:100%;aspect-ratio:16/7;border:none;border-bottom:1px solid var(--line)}
.nx-card.lead .nx-body{padding:20px 22px 18px}
.nx-card.lead .nx-title{font-size:26px;letter-spacing:-.032em;line-height:1.18;margin-bottom:9px}
.nx-card.lead .nx-sum{font-size:14.5px;-webkit-line-clamp:3;margin-bottom:16px}
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ HR controls: outside the anchor, since links cannot nest ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.nx-admin{position:absolute;top:10px;right:10px;display:flex;gap:6px;opacity:0;
  transition:opacity .15s;z-index:2}
.nx-item:hover .nx-admin,.nx-admin:focus-within{opacity:1}
.nx-admin a{font-size:11px;font-weight:700;padding:5px 10px;background:var(--paper-2);
  border:1px solid var(--line-2);color:var(--ink);text-decoration:none;transition:.13s}
.nx-admin a:hover{background:var(--ink);color:var(--paper-2);border-color:var(--ink)}
.nx-card.lead+.nx-admin{top:14px;right:14px}
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ empty state ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.nx-empty{border:1px dashed var(--line-2);background:var(--paper-2);padding:56px 30px;
  text-align:center}
.nx-empty svg{width:34px;height:34px;color:var(--line-2);margin-bottom:12px}
.nx-empty h3{font-size:16px;letter-spacing:-.01em;margin-bottom:6px}
.nx-empty p{font-size:13.5px;color:var(--muted);margin-bottom:16px}
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ pagination ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.nx-pages{display:flex;align-items:center;gap:6px;margin-top:22px;padding-top:18px;
  border-top:1px solid var(--line);flex-wrap:wrap}
.nx-pg{min-width:34px;height:34px;padding:0 11px;display:inline-flex;align-items:center;
  justify-content:center;border:1px solid var(--line-2);background:var(--paper-2);
  font-size:12.5px;font-weight:700;color:var(--ink);text-decoration:none;transition:.13s}
.nx-pg:hover{background:var(--yellow);border-color:var(--yellow);color:var(--on-yellow)}
.nx-pg.on{background:var(--ink);border-color:var(--ink);color:var(--paper-2);pointer-events:none}
.nx-pg.off{opacity:.35;pointer-events:none}
.nx-pgi{margin-left:auto;font-size:12px;color:var(--muted);font-weight:600}
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ sidebar ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.nx-side{position:sticky;top:84px;display:flex;flex-direction:column;gap:16px}
.nx-panel{background:var(--paper-2);border:1px solid var(--line)}
.nx-ph{display:flex;align-items:center;gap:8px;padding:13px 16px;border-bottom:1px solid var(--line);
  font-size:10.5px;font-weight:800;letter-spacing:.13em;text-transform:uppercase;color:var(--muted)}
.nx-ph::before{content:"";width:7px;height:7px;background:var(--yellow);flex:none;color:var(--on-yellow)}
.nx-ph .sub{margin-left:auto;letter-spacing:.04em;font-weight:600;text-transform:none;font-size:10.5px;opacity:.8}
.nx-pb{padding:6px 16px 14px}
/* stats */
.nx-stats{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line)}
.nx-stat{background:var(--paper-2);padding:14px 16px}
.nx-stat b{display:block;font-size:23px;font-weight:700;letter-spacing:-.03em;line-height:1}
.nx-stat span{display:block;font-size:10.5px;font-weight:700;letter-spacing:.08em;
  text-transform:uppercase;color:var(--muted);margin-top:5px}
/* trending */
.nx-tr{display:flex;gap:11px;padding:11px 0;border-bottom:1px solid var(--line);
  text-decoration:none;color:inherit}
.nx-tr:last-child{border-bottom:none}
.nx-tr-n{font-size:15px;font-weight:800;color:var(--muted);line-height:1.1;flex:none;width:17px;
  transition:color .14s}
.nx-tr:hover .nx-tr-n{color:var(--ink)}
.nx-tr-t{font-size:12.8px;font-weight:700;line-height:1.35;letter-spacing:-.01em;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.nx-tr:hover .nx-tr-t{text-decoration:underline;text-underline-offset:2px}
.nx-tr-m{font-size:10.5px;color:var(--muted);margin-top:3px;display:flex;gap:9px}
/* categories */
.nx-cl{display:flex;flex-direction:column}
.nx-cl a{display:flex;align-items:center;justify-content:space-between;gap:10px;
  padding:9px 0;border-bottom:1px solid var(--line);font-size:13px;font-weight:600;
  color:var(--ink-2);text-decoration:none;transition:.13s}
.nx-cl a:last-child{border-bottom:none}
.nx-cl a:hover{color:var(--ink);padding-left:5px}
.nx-cl a.on{color:var(--ink);font-weight:800}
.nx-cl .c{font-size:11px;font-weight:700;color:var(--muted);background:var(--paper-3);
  padding:2px 8px;min-width:24px;text-align:center}
.nx-cl a.on .c{background:var(--yellow);color:var(--on-yellow)}
/* comments */
.nx-cm{display:flex;gap:10px;padding:11px 0;border-bottom:1px solid var(--line)}
.nx-cm:last-child{border-bottom:none}
.nx-cm-av{width:26px;height:26px;border-radius:50%;background:var(--paper-3);color:var(--ink);
  display:flex;align-items:center;justify-content:center;font-size:9.5px;font-weight:800;flex:none}
.nx-cm-b{min-width:0}
.nx-cm-w{font-size:12px;font-weight:700}
.nx-cm-t{font-size:12px;color:var(--muted);line-height:1.45;margin-top:2px;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.nx-cm-a{font-size:10.5px;margin-top:4px;color:var(--muted);text-decoration:none;
  display:inline-block;font-weight:700}
.nx-cm-a:hover{color:var(--ink);text-decoration:underline}
/* events */
.nx-ev{display:flex;gap:11px;padding:10px 0;border-bottom:1px solid var(--line);align-items:center}
.nx-ev:last-child{border-bottom:none}
.nx-ev-d{flex:none;width:38px;text-align:center;background:var(--paper-3);padding:5px 0}
.nx-ev-d .m{font-size:8.5px;font-weight:800;letter-spacing:.08em;color:var(--muted)}
.nx-ev-d .n{font-size:15px;font-weight:800;line-height:1.05}
.nx-ev-t{font-size:12.5px;font-weight:700;line-height:1.3}
.nx-ev-s{font-size:10.5px;color:var(--muted);margin-top:2px}
.nx-side-empty{font-size:12.5px;color:var(--muted);padding:6px 0 4px}
@media(max-width:1080px){
  .nx-shell{grid-template-columns:1fr}
  .nx-side{position:static;flex-direction:row;flex-wrap:wrap}
  .nx-side>.nx-panel{flex:1;min-width:270px}
}
@media(max-width:620px){
  .nx-card{flex-direction:column;gap:14px}
  .nx-thumb{width:100%}
  .nx-side{flex-direction:column}
}

/* from content\_feature_people_culture.html ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â 48 rules */
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ PC-BOX layout ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.pc-box{display:flex;gap:0;border:1px solid var(--line);background:var(--paper-2);overflow:hidden;align-items:stretch;min-height:380px;margin-bottom:28px}
.pc-side{width:240px;flex:none;border-right:1px solid var(--line);background:var(--paper-2);padding:10px;display:flex;flex-direction:column;gap:4px}
.pc-tab{display:flex;align-items:center;gap:11px;width:100%;text-align:left;border:1px solid transparent;background:transparent;padding:13px;font-family:inherit;font-size:13.5px;font-weight:600;color:var(--ink);cursor:pointer;border-radius:0;transition:background .13s,border-color .13s;text-decoration:none}
.pc-tab span{flex:1}
.pc-tab .chev{opacity:.35;transition:transform .14s}
.pc-tab:hover{background:var(--paper-2);border-color:var(--line)}
.pc-tab.on{background:var(--yellow);color:var(--on-yellow)}
.pc-tab.on svg{color:var(--on-yellow)}
.pc-tab.on .chev{opacity:.8;transform:translateX(2px)}
.pc-content{flex:1;min-width:0;padding:22px;overflow-y:auto}
.pc-content .card{background:var(--paper)}
.pc-panel{display:none}
.pc-panel.active{display:block}
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ meet the team ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.team-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.team-card{border:1px solid var(--line);background:var(--paper-2);padding:24px 20px;display:flex;flex-direction:column;align-items:center;text-align:center;transition:box-shadow .16s,border-color .16s}
.team-card:hover{box-shadow:0 8px 22px rgba(18,18,16,.07);border-color:var(--line-2)}
.team-photo{width:104px;height:104px;border-radius:50%;overflow:hidden;margin-bottom:15px;flex:none}
.team-photo img{width:100%;height:100%;object-fit:cover;object-position:center 20%;display:block}
.team-initials{display:flex;align-items:center;justify-content:center;font-weight:700;font-size:34px;color:var(--yellow);background:linear-gradient(135deg,var(--ink),#3a3a38)}
.team-name{font-weight:700;font-size:16px;letter-spacing:-.01em}
.team-role{color:var(--muted);font-size:12.5px;margin-top:3px}
.team-actions{display:flex;gap:8px;margin-top:14px;flex-wrap:wrap;justify-content:center}
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ tiles (comm channels) ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:28px}
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ cert badges ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.cert-badge{display:inline-flex;align-items:center;gap:8px;font-weight:700;font-size:15px;letter-spacing:.02em;padding:11px 18px;border:1px solid var(--line-2);background:var(--paper-2);box-shadow:0 1px 2px rgba(18,18,16,.04)}
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ partner chips ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.partner-chip{display:inline-block;padding:6px 13px;border:1px solid var(--line-2);background:var(--paper-2);font-size:12.5px;font-weight:600;margin:4px}
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Employee Handbook hero ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.hb-hero{display:flex;align-items:center;gap:20px;flex-wrap:wrap;border-left:3px solid var(--yellow)}
.hb-icon{width:60px;height:60px;background:var(--yellow);display:flex;align-items:center;justify-content:center;flex:none;color:var(--on-yellow)}
.hb-text{flex:1;min-width:250px}
.hb-meta{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:11px;font-size:11.5px;color:var(--muted);font-weight:600}
.hb-dot{opacity:.5}
.hb-acts{display:flex;gap:10px;flex-wrap:wrap;flex:none}
/* HR Information feed styles live in aji_hub.css ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â shared with the article page. */

/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ WhatsApp channels modal ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.wa-bg{position:fixed;inset:0;background:rgba(18,18,16,.5);z-index:900;display:none}
.wa-bg.on{display:block}
.wa{position:fixed;z-index:901;top:50%;left:50%;transform:translate(-50%,-50%);
  width:min(700px,94vw);max-height:90vh;overflow-y:auto;background:var(--paper-2);
  border:1px solid var(--line-2);box-shadow:0 22px 60px -20px rgba(18,18,16,.5);padding:24px;display:none}
.wa.on{display:block}
.wa-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:18px}
.wa-head h3{font-size:19px;letter-spacing:-.02em;margin:0 0 4px}
.wa-x{background:none;border:none;font-size:22px;line-height:1;color:var(--muted);cursor:pointer;font-family:inherit}
.wa-x:hover{color:var(--ink)}
.wa-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px}
.wa-ch{border:1px solid var(--line);background:var(--paper-2);padding:18px;text-align:center}
.wa-qr{width:170px;height:170px;margin:0 auto 13px;background:var(--paper-3);display:flex;
  align-items:center;justify-content:center;border:1px solid var(--line)}
.wa-qr img{width:100%;height:100%;object-fit:contain;display:block}
.wa-ch h4{font-size:14.5px;margin:0 0 4px}
.wa-ch p{font-size:12.5px;color:var(--muted);margin:0 0 12px;line-height:1.5}
@media(max-width:820px){.pc-box{flex-direction:column}.pc-side{width:100%;flex-direction:row;flex-wrap:wrap;border-right:none;border-bottom:1px solid var(--line)}.pc-tab{width:auto}.pc-tab .chev{display:none}}
@media(max-width:700px){.team-grid{grid-template-columns:1fr 1fr}.tiles{grid-template-columns:1fr}}
@media(max-width:480px){.team-grid{grid-template-columns:1fr}}

/* from content\_feature_portfolio.html ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â 19 rules */
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Filter bar ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.pf-bar{background:var(--paper-2);border:1px solid var(--line);padding:16px 20px;margin-bottom:20px;display:flex;gap:12px;flex-wrap:wrap;align-items:center}
.pf-bar select{border:1px solid var(--line-2);padding:9px 30px 9px 12px;font-family:inherit;font-size:13px;outline:none;background:var(--paper-2) url("data:image/svg+xml,%3Csvg width='12' height='12' viewBox='0 0 24 24' fill='none' stroke='%23888' stroke-width='2' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='m6 9 6 6 6-6'/%3E%3C/svg%3E") no-repeat right 10px center;appearance:none;-webkit-appearance:none;cursor:pointer;transition:border-color .13s;min-width:130px}
.pf-bar select:focus{border-color:var(--ink)}
.pf-count{font-size:13px;color:var(--muted);margin-left:auto;white-space:nowrap}
/* The search box. Grows to fill the bar so the typing area is the biggest
   thing on it, which is what it is for. */
.pf-find{position:relative;display:flex;align-items:center;gap:8px;flex:1 1 260px;
  min-width:220px;border:1px solid var(--line-2);background:var(--paper-2);padding:0 10px}
.pf-find:focus-within{border-color:var(--ink)}
.pf-find > svg{flex:none;color:var(--muted-2)}
.pf-find input{flex:1;min-width:0;border:none;outline:none;background:none;
  font-family:inherit;font-size:13.5px;padding:9px 0;color:var(--ink)}
.pf-find-x{flex:none;border:none;background:none;cursor:pointer;color:var(--muted-2);
  display:flex;padding:4px;border-radius:50%}
.pf-find-x:hover{color:var(--ink);background:var(--paper-3)}
/* Results being replaced. Dimmed rather than emptied: a grid that blinks out on
   every keystroke is harder to read than one that fades while it catches up. */
.pf-grid.searching{opacity:.45;transition:opacity .12s}
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Grid ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.pf-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:20px}
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Card ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
/* Every card the same height, always.
   The parts each hold their own line count rather than the card being told a
   total, so the sizes still follow the type if the type changes. A card is:
   picture 200 + title 2 lines + location 1 + description 2. Nothing on a card
   is allowed to push it taller, and nothing missing is allowed to pull it
   shorter — the empty lines below are reserved, not skipped. */
.proj{border:none;background:transparent;overflow:hidden;cursor:pointer;transition:transform .15s;
  display:flex;flex-direction:column}
.proj:hover{transform:translateY(-3px)}
.proj:hover .pf-img{box-shadow:0 8px 32px rgba(18,18,16,.2)}
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Image banner ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.pf-img{position:relative;height:200px;flex:none;overflow:hidden;background:#0b0b0b;transition:box-shadow .15s}
.pf-img img{width:100%;height:100%;object-fit:cover;display:block}
/* mesh grid overlay */
.pf-img::after{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px);background-size:28px 28px;pointer-events:none;z-index:2}
/* Entity badge ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â dark, top left, flush to edge */
.pf-entity{position:absolute;top:0;left:0;z-index:3;background:var(--ink);color:var(--paper-2);font-size:10.5px;font-weight:700;letter-spacing:.04em;padding:6px 12px;white-space:nowrap}
/* Type badge ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â yellow, directly below entity */
.pf-type{position:absolute;top:30px;left:0;z-index:3;background:var(--yellow);color:var(--on-yellow);font-size:10.5px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;padding:6px 12px;white-space:nowrap}
/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Card body below image ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ */
.pf-body{background:var(--paper-2);padding:14px 4px 16px;flex:1;display:flex;flex-direction:column}
/* Two lines, whether the title needs one or three. A long name is cut rather
   than allowed to set the height of its whole row. */
.pf-title{font-weight:800;font-size:17px;letter-spacing:-.02em;color:var(--ink);
  margin-bottom:7px;line-height:1.2;height:2.4em;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
/* One line, kept even when there is no location to put on it. */
.pf-loc{font-size:13px;color:var(--muted);display:flex;align-items:center;gap:5px;
  margin-bottom:14px;height:1.4em;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.pf-loc svg{flex:none}
.pf-footer{border-top:1px solid var(--line);padding-top:10px;font-size:13px;font-weight:700;color:var(--muted)}
/* What the project is, under the rule where the division and year used to be.
   Clamped to two lines: these come from a spreadsheet and run to 1,350
   characters at the longest, so without a ceiling one card would be six times
   the height of the one beside it and the grid would come apart. */
/* A project with no photograph. Drawn, not fetched — every one of these used
   to be a request to picsum.photos taking about a second, twenty-eight of them
   before the first screen of the portfolio had finished loading. */
.pf-noimg{position:absolute;inset:0;display:flex;align-items:center;
  justify-content:center;background:var(--paper-3);color:var(--muted-2);
  font-size:30px;font-weight:800;letter-spacing:.06em;
  background-image:linear-gradient(135deg,rgba(18,18,16,.05) 25%,transparent 25%,
    transparent 50%,rgba(18,18,16,.05) 50%,rgba(18,18,16,.05) 75%,transparent 75%);
  background-size:16px 16px}
/* The opt-in stand-in reads as deliberately provisional rather than as a
   photograph somebody forgot to replace. */
.pf-noimg.dummy{background-color:var(--paper);color:var(--line-2)}
.slide.noimg{background:linear-gradient(160deg,#1b1b18,#0b0b0a)}
.booth-card.noimg{background:linear-gradient(160deg,#26261f,#0f0f0d)}

.pf-desc{border-top:1px solid var(--line);padding-top:10px;font-size:12.5px;
  line-height:1.55;color:var(--ink-2);font-weight:400;margin-top:auto;
  height:calc(3.1em + 10px);
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
/* No description written yet. The space stays — the card has to match the ones
