.ed-pal-in{width:min(980px,100%)}
.ed-pal-hd{align-items:flex-start}
.ed-pal-sub{margin:3px 0 0;font-size:12.5px;color:var(--muted);line-height:1.5}

/* Search sits above the grid and is focused when the palette opens, so the
   fastest path is: open, type two letters, press Enter. */
.ed-pal-search{display:flex;align-items:center;gap:var(--sp-2);
  padding:var(--sp-3) var(--sp-5);border-bottom:1px solid var(--line);
  background:var(--paper)}
.ed-pal-search svg{color:var(--muted);flex:none}
.ed-pal-search input{flex:1;border:none;background:transparent;font-family:inherit;
  font-size:14px;color:var(--ink);padding:var(--sp-1) 0}
.ed-pal-search input:focus{outline:none}
.ed-pal-count{font-size:11.5px;color:var(--muted);font-weight:600;flex:none}

.ed-pal-gr{grid-template-columns:repeat(auto-fill,minmax(196px,1fr));
  gap:var(--sp-3);max-height:64vh;overflow:auto;align-content:start}
.ed-pal-b{display:flex;flex-direction:column;gap:var(--sp-2);padding:var(--sp-3);
  text-align:left}
.ed-pal-b b{font-size:12.5px;margin:0}
.ed-pal-hint{display:none}          /* the title attribute carries it instead */
.ed-pal-b.kb{border-color:var(--ink);box-shadow:0 0 0 2px var(--yellow)}
.ed-pal-none{display:none;grid-column:1/-1;text-align:center;color:var(--muted);
  font-size:13px;padding:var(--sp-6) 0;margin:0}

/* ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ The wireframe itself ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
   A schematic, not a render: it always shows the shape even when the page has
   no news, no events and nobody's birthday. */
.wf{display:flex;flex-direction:column;gap:3px;height:74px;padding:7px 8px;
  background:var(--paper);border:1px solid var(--line);overflow:hidden;
  justify-content:flex-start}
.wf s{display:block;background:var(--line-2);border-radius:1px;flex:none;
  text-decoration:none;height:5px}
.wf s.t{height:8px;background:var(--ink-3)}
.wf s.b{height:4px}
.wf s.mut{background:var(--line)}
.wf s.on{background:var(--yellow);color:var(--on-yellow)}
.wf .w30{width:30%}.wf .w40{width:40%}.wf .w50{width:50%}.wf .w60{width:60%}
.wf .w70{width:70%}.wf .w80{width:80%}.wf .w90{width:90%}.wf .w100{width:100%}
.wf s.x{flex:1;min-height:20px;background:var(--paper-2);border:1px solid var(--line-2);
  height:auto}
.wf s.x.sm{min-height:14px}
.wf s.x.ico{background:var(--paper-2);position:relative}
.wf s.x.ico::before{content:"";position:absolute;top:3px;left:3px;width:7px;height:7px;
  background:var(--yellow);color:var(--on-yellow)}
.wf s.x.img{background:repeating-linear-gradient(45deg,var(--line) 0 3px,var(--paper-2) 3px 6px)}
.wf s.x.person::before,.wf s.x.face::before{content:"";position:absolute;top:4px;left:50%;
  transform:translateX(-50%);width:9px;height:9px;border-radius:50%;background:var(--line-2)}
.wf s.x.person,.wf s.x.face{position:relative}
.wf s.i{width:9px;height:9px;border-radius:50%;background:var(--line-2)}
.wf s.pill{width:16px;height:6px;background:var(--yellow);color:var(--on-yellow)}
.wf s.date{width:13px;height:14px;background:var(--ink-3)}
.wf s.time{width:12px;height:4px;background:var(--muted-2)}
.wf s.btn{width:22px;height:7px;background:var(--line-2)}
.wf s.btn.on{background:var(--yellow);color:var(--on-yellow)}
.wf s.chev{width:5px;height:5px;margin-left:auto;background:var(--line-2)}
.wf s.n{width:60%;height:10px;background:var(--ink-3)}

.wf .wf-row{display:flex;gap:4px;flex:1}
.wf .wf-col{flex:1;display:flex}
.wf .wf-grid{display:grid;gap:4px;flex:1}
.wf .wf-grid.g2{grid-template-columns:repeat(2,1fr)}
.wf .wf-grid.g3{grid-template-columns:repeat(3,1fr)}
.wf .wf-grid.g4{grid-template-columns:repeat(4,1fr)}
.wf .wf-grid.g6{grid-template-columns:repeat(6,1fr)}
.wf .wf-grid.tight{gap:2px}
.wf .wf-split{display:flex;gap:6px;align-items:flex-start}
.wf .wf-split>div{flex:1;display:flex;flex-direction:column;gap:3px}
.wf .wf-split>s.x{width:30%;flex:none;min-height:26px}
.wf .wf-card{border:1px solid var(--line-2);background:var(--paper-2);padding:5px;
  display:flex;flex-direction:column;gap:3px;flex:1}
.wf .wf-line{display:flex;align-items:center;gap:4px;padding-bottom:3px;
  border-bottom:1px solid var(--line)}
.wf .wf-line:last-child{border-bottom:none;padding-bottom:0}
.wf .wf-line.open{padding:4px;background:var(--paper)}
.wf .wf-hero{flex:1;background:var(--bed);display:flex;flex-direction:column;
  justify-content:flex-end;gap:3px;padding:6px}
.wf .wf-note{flex:1;border-left:3px solid var(--yellow);background:var(--paper-2);
  padding:5px;display:flex;flex-direction:column;gap:3px}
.wf .wf-quote{flex:1;border-left:3px solid var(--line-2);padding-left:6px;
  display:flex;flex-direction:column;gap:4px;justify-content:center}
.wf .wf-stats{display:flex;gap:6px;margin-top:auto}
.wf .wf-stats.tight{margin-top:3px}
.wf .wf-stats span{flex:1;display:flex;flex-direction:column;gap:2px}
.wf .wf-time{flex:1;display:flex;flex-direction:column;gap:5px;
  border-left:1px solid var(--line-2);padding-left:6px}
.wf .wf-time>div{display:flex;align-items:center;gap:5px}
.wf .wf-tabs{flex:1;display:flex;gap:4px;border:1px solid var(--line-2);
  background:var(--paper-2)}
.wf .wf-side{width:32%;border-right:1px solid var(--line);padding:4px;
  display:flex;flex-direction:column;gap:3px}
.wf .wf-side s{width:100%;height:6px}
.wf .wf-pane{flex:1;padding:4px;display:flex;flex-direction:column;gap:3px}
.wf .wf-table{flex:1;display:flex;flex-direction:column;border:1px solid var(--line-2)}
.wf .wf-table>div{display:flex;flex:1;border-bottom:1px solid var(--line)}
.wf .wf-table>div:last-child{border-bottom:none}
.wf .wf-table>div.hd{background:var(--paper-3)}
.wf .wf-table s{flex:1;height:auto;margin:3px;background:var(--line)}
.wf .wf-video{flex:1;background:var(--ink-3);display:flex;align-items:center;
  justify-content:center}
.wf s.play{width:0;height:0;background:none;border-left:9px solid var(--yellow);
  border-top:6px solid transparent;border-bottom:6px solid transparent}
.wf .wf-btns{display:flex;gap:5px;align-items:center;flex:1}
.wf .wf-btns s{height:11px;width:34px}
.wf .wf-reel{flex:1;background:var(--bed);padding:6px;display:flex;
  flex-direction:column;justify-content:flex-end;gap:3px;position:relative}
.wf s.dots{position:absolute;right:6px;bottom:6px;width:18px;height:3px;
  background:var(--yellow);color:var(--on-yellow)}
.wf .wf-div{flex:1;display:flex;align-items:center}
.wf .wf-div s{width:100%;height:1px;background:var(--line-2)}
.wf .wf-code{flex:1;background:var(--paper-3);padding:5px;display:flex;
  flex-direction:column;gap:3px;font-family:var(--mono)}
.wf .wf-feature{flex:1;border:1px dashed var(--line-2);background:var(--paper-2);
  padding:5px;display:flex;flex-direction:column;gap:3px;position:relative}
